import sys

def solve():
    line = sys.stdin.read().split()
    if not line:
        return
    n = int(line[0])
    l = int(line[1])
    r = int(line[2])

    def count_ones_in_range(n_val, current_len, target_l, target_r):
        if n_val == 0:
            return 0
        if n_val == 1:
            return 1

        left_len = current_len // 2
        mid = left_len + 1
        right_len = left_len

        total = 0

        if target_l <= mid <= target_r:
            total += 1

        if target_l <= mid:
            total += count_ones_in_range(n_val // 2, left_len, target_l, min(target_r, mid))

        if target_r > mid:
            total += count_ones_in_range(n_val // 4, right_len, max(1, target_l - mid), target_r - mid)

        return total

    def get_final_length(n_val):
        if n_val == 0:
            return 1
        if n_val == 1:
            return 1
        left_len = get_final_length(n_val // 2)
        return left_len + 1 + left_len

    final_len = get_final_length(n)

    ans = count_ones_in_range(n, final_len, l, r)
    print(ans)

if __name__ == "__main__":
    solve()
